// Whole check fields retain their grammar masks and authored coordinates. A
// target edit changes only the selected field words and their isolated targets.
func agreementCoupledMappedCodeCheckFields(body, private string, source, changed *agreementMappedCodeP2Reading, fields []agreementMappedCodeP2Field) (int, bool) {
	if source == nil || changed == nil || !source.Valid || !changed.Valid || len(fields) == 0 || len(body) != len(private) || strings.Contains(body, "q") || !slices.Equal(source.Check.Code, changed.Check.Code) || !slices.Equal(source.Check.Comments, changed.Check.Comments) || len(source.Check.Fields) != len(changed.Check.Fields) {
		return 0, false
	}
	expectedBody := []byte(body)
	expectedFields := slices.Clone(source.Check.Fields)
	seen := make(map[int]bool)
	active := 0
	for _, field := range fields {
		span := field.OriginalTarget
		if span.Start < 0 || span.Stop > len(body) || span.Start >= span.Stop || body[span.Start:span.Stop] != field.Old || field.New != strings.Repeat("q", len(field.Old)) {
			return 0, false
		}
		index := -1
		for i, checkField := range source.Check.Fields {
			if checkField.Span != field.OriginalField {
				continue
			}
			if index >= 0 {
				return 0, false
			}
			index = i
		}
		if index < 0 || seen[index] {
			return 0, false
		}
		seen[index] = true
		old := source.Check.Fields[index]
		if old.Span.Start < 0 || old.Span.Stop > len(body) || old.Span.Start > span.Start || old.Span.Stop < span.Stop || old.Word != body[old.Span.Start:old.Span.Stop] || !slices.Equal(old.Targets, []string{field.Old}) {
			return 0, false
		}
		copy(expectedBody[span.Start:span.Stop], field.New)
		at := span.Start - old.Span.Start
		expectedFields[index].Word = old.Word[:at] + field.New + old.Word[at+len(field.Old):]
		expectedFields[index].Targets = []string{field.New}
		if !old.Code && !old.Comment && !old.Escaped {
			active++
		}
	}
	if string(expectedBody) != private || !cmp.Equal(expectedFields, changed.Check.Fields) {
		return 0, false
	}
	fromFields := func(fields []agreementNativeCheckField) []string {
		var targets []string
		for _, field := range fields {
			if !field.Code && !field.Comment && !field.Escaped {
				targets = append(targets, field.Targets...)
			}
		}
		return targets
	}
	if !slices.Equal(fromFields(source.Check.Fields), source.Check.Targets) || !slices.Equal(fromFields(expectedFields), changed.Check.Targets) {
		return 0, false
	}
	return active, true
}

func agreementCoupledMappedCodeP1Counts(page *agreementHTML, source *agreementMappedCodeP2Reading) map[string]int {
	counts := make(map[string]int)
	for _, citation := range page.Citations {
		if citation.SourceRole == "" && citation.Target != "" {
			counts[citation.Target]++
		}
	}
	for _, target := range source.Check.Targets {
		counts[target]--
	}
	for target, count := range counts {
		if count == 0 {
			delete(counts, target)
		}
	}
	return counts
}

func agreementCoupledMappedCodeP1Pool(counts map[string]int) map[string]int {
	pool := make(map[string]int)
	for target, count := range counts {
		if count == 0 {
			continue
		}
		direction := "page-only"
		if count < 0 {
			direction, count = "judge-only", -count
		}
		f := agreementFailure{Property: "P1", Identity: "citation-occurrences", Tuple: agreementCitation{Target: target}, Direction: direction, Multiplicity: count}
		pool[agreementSignature(&f)]++
	}
	return pool
}

// The complete P1 set is predicted from whole source targets and public
// citations. Quiet code fields account for the page-only target transfer.
func agreementCoupledMappedCodeSignedProjection(before, after []agreementFailure, source, changed *agreementMappedCodeP2Reading, page, privatePage *agreementHTML, selected *agreementFailure, count, active int) bool {
	if source == nil || changed == nil || page == nil || privatePage == nil || selected == nil || active < 0 || active > count || count < 1 || count > selected.Multiplicity {
		return false
	}
	oldCounts := agreementCoupledMappedCodeP1Counts(page, source)
	newCounts := agreementCoupledMappedCodeP1Counts(privatePage, changed)
	wantCounts := maps.Clone(oldCounts)
	target := selected.Tuple.Target
	replacement := strings.Repeat("q", len(target))
	if target == "" || oldCounts[replacement] != 0 {
		return false
	}
	quiet := count - active
	wantCounts[target] -= quiet
	wantCounts[replacement] += quiet
	for key, n := range wantCounts {
		if n == 0 {
			delete(wantCounts, key)
		}
	}
	if !maps.Equal(wantCounts, newCounts) {
		return false
	}
	split := func(rows []agreementFailure) ([]agreementFailure, map[string]int) {
		var other []agreementFailure
		p1 := make(map[string]int)
		for i := range rows {
			if rows[i].Property == "P1" {
				p1[agreementSignature(&rows[i])]++
			} else {
				other = append(other, rows[i])
			}
		}
		return other, p1
	}
	oldOther, oldP1 := split(before)
	newOther, newP1 := split(after)
	return maps.Equal(oldP1, agreementCoupledMappedCodeP1Pool(oldCounts)) && maps.Equal(newP1, agreementCoupledMappedCodeP1Pool(wantCounts)) && agreementMappedCodeP2SignedProjection(oldOther, newOther, selected, replacement, count)
}

func agreementCoupledMappedCodePublicProjection(source, private *agreementMappedCodeP2Reading, page, privatePage *agreementHTML, parts, privateParts [][]agreementCodePart, f *agreementFailure, count, active int) bool {
	if source == nil || private == nil || page == nil || privatePage == nil || f == nil || !source.Valid || !private.Valid || count < 1 || count > f.Multiplicity || active < 0 || active > count || !slices.Equal(source.NeutralPositions, private.NeutralPositions) || len(source.NeutralPage) != len(parts) || len(private.NeutralPage) != len(privateParts) {
		return false
	}
	oldBudget, privateBudget := make(map[agreementCitation]int), make(map[agreementCitation]int)
	for i, window := range source.NeutralPage {
		owned, valid := agreementMatchCodeWindow(window.Text, parts[i])
		if !valid {
			return false
		}
		for tuple, n := range owned {
			oldBudget[tuple] += n
		}
	}
	for i, window := range private.NeutralPage {
		owned, valid := agreementMatchCodeWindow(window.Text, privateParts[i])
		if !valid {
			return false
		}
		for tuple, n := range owned {
			privateBudget[tuple] += n
		}
	}
	if !maps.Equal(oldBudget, agreementMappedCodeP2CitationCounts(page.CodeCitations)) || !maps.Equal(privateBudget, agreementMappedCodeP2CitationCounts(privatePage.CodeCitations)) || oldBudget[f.Tuple] != f.Multiplicity || page.CitationsInCode != len(page.CodeCitations) || privatePage.CitationsInCode != len(privatePage.CodeCitations) {
		return false
	}
	newTuple := f.Tuple
	newTuple.Target = strings.Repeat("q", len(f.Tuple.Target))
	for _, pair := range [][2]map[agreementCitation]int{{oldBudget, privateBudget}, {agreementMappedCodeP2CitationCounts(page.Citations), agreementMappedCodeP2CitationCounts(privatePage.Citations)}} {
		want := maps.Clone(pair[0])
		if want[f.Tuple] < count || want[newTuple] != 0 {
			return false
		}
		want[f.Tuple] -= count
		if want[f.Tuple] == 0 {
			delete(want, f.Tuple)
		}
		want[newTuple] = count
		if !maps.Equal(want, pair[1]) {
			return false
		}
	}
	if !cmp.Equal(page.Blocks, privatePage.Blocks) || !cmp.Equal(page.Headings, privatePage.Headings) || !cmp.Equal(page.CalloutTitles, privatePage.CalloutTitles) || !cmp.Equal(page.Failures, privatePage.Failures) || page.CitationsInCode != privatePage.CitationsInCode || !cmp.Equal(source.Native, private.Native) || !cmp.Equal(source.Tree, private.Tree) || !cmp.Equal(source.Sites, private.Sites) || !cmp.Equal(source.HTMLSites, private.HTMLSites) {
		return false
	}
	oldTargets, privateTargets := make(map[string]int), make(map[string]int)
	for _, target := range source.Check.Targets {
		oldTargets[target]++
	}
	for _, target := range private.Check.Targets {
		privateTargets[target]++
	}
	if oldTargets[f.Tuple.Target]-privateTargets[f.Tuple.Target] != active || privateTargets[newTuple.Target]-oldTargets[newTuple.Target] != active || oldTargets[newTuple.Target] != 0 {
		return false
	}
	delete(oldTargets, f.Tuple.Target)
	delete(oldTargets, newTuple.Target)
	delete(privateTargets, f.Tuple.Target)
	delete(privateTargets, newTuple.Target)
	return maps.Equal(oldTargets, privateTargets)
}

func agreementCoupledMappedCodeProjection(r *agreementMappedCodeP2Declaration) bool {
	if r == nil || len(r.Fields) == 0 || len(r.Singles) != len(r.Fields) {
		return false
	}
	var selected *agreementFailure
	for i := range r.Before {
		if agreementSignature(&r.Before[i]) == r.Selected {
			if selected != nil {
				return false
			}
			selected = &r.Before[i]
		}
	}
	active, checkValid := agreementCoupledMappedCodeCheckFields(r.Body, r.Private, &r.Source, &r.PrivateSource, r.Fields)
	if !checkValid || active >= len(r.Fields) || selected == nil || len(r.Fields) != selected.Multiplicity || !agreementCoupledMappedCodeSignedProjection(r.Before, r.After, &r.Source, &r.PrivateSource, &r.Page, &r.PrivatePage, selected, len(r.Fields), active) || !agreementCoupledMappedCodePublicProjection(&r.Source, &r.PrivateSource, &r.Page, &r.PrivatePage, r.Parts, r.PrivateParts, selected, len(r.Fields), active) {
		return false
	}
	whole := []byte(r.Body)
	expected := slices.Clone(r.Diagnostics)
	seen := make(map[int]bool)
	for i, field := range r.Fields {
		single := &r.Singles[i]
		span := field.OriginalTarget
		if single.Field != i || span.Start < 0 || span.Stop > len(r.Body) || span.Start >= span.Stop || r.Body[span.Start:span.Stop] != selected.Tuple.Target || field.Old != selected.Tuple.Target || field.New != strings.Repeat("q", len(field.Old)) || len(r.Diagnostics) != len(single.Diagnostics) || single.DiagnosticIndex < 0 || single.DiagnosticIndex >= len(r.Diagnostics) || seen[single.DiagnosticIndex] {
			return false
		}
		seen[single.DiagnosticIndex] = true
		one := []byte(r.Body)
		copy(one[span.Start:span.Stop], field.New)
		copy(whole[span.Start:span.Stop], field.New)
		singleActive, singleCheckValid := agreementCoupledMappedCodeCheckFields(r.Body, single.Body, &r.Source, &single.Source, []agreementMappedCodeP2Field{field})
		if !singleCheckValid || string(one) != single.Body || !agreementCoupledMappedCodeSignedProjection(r.Before, single.Failures, &r.Source, &single.Source, &r.Page, &single.Page, selected, 1, singleActive) || !agreementCoupledMappedCodePublicProjection(&r.Source, &single.Source, &r.Page, &single.Page, r.Parts, single.Parts, selected, 1, singleActive) {
			return false
		}
		for di, old := range r.Diagnostics {
			changed := single.Diagnostics[di]
			if di != single.DiagnosticIndex {
				if !cmp.Equal(old, changed) {
					return false
				}
				continue
			}
			if old.Kind != render.DiagWikilinkBroken || old.Target != field.Old || changed.Target != field.New || old.Kind != changed.Kind || old.Section != changed.Section || old.Block != changed.Block || changed.Message != strings.ReplaceAll(old.Message, strconv.Quote(field.Old), strconv.Quote(field.New)) {
				return false
			}
			expected[di] = changed
		}
	}
	return string(whole) == r.Private && cmp.Equal(expected, r.PrivateDiagnostics)
}

func agreementCoupledMappedCodeReadDeclaration(t *testing.T, body, name, signature string) (agreementMappedCodeP2Declaration, bool) {
	t.Helper()
	r := agreementMappedCodeP2Declaration{Body: body, Case: name, Selected: signature, Source: agreementMappedCodeP2Read(body)}
	raw, page, before := agreementProseP1Failures(t, body)
	r.HTML, r.Page, r.Before, r.Diagnostics = raw.HTML, page, before, raw.Diagnostics
	var selected *agreementFailure
	for i := range before {
		if agreementSignature(&before[i]) == signature {
			if selected != nil {
				return r, false
			}
			selected = &before[i]
		}
	}
	var partsOK bool
	r.Parts, partsOK = agreementCodeWindowParts(raw.HTML)
	if !partsOK {
		return r, false
	}
	private, fields, owned := agreementMappedCodeP2Physical(body, selected, &r.Source, r.Parts)
	if !owned {
		return r, false
	}
	r.Private, r.Fields, r.PrivateSource = private, fields, agreementMappedCodeP2Read(private)
	pr, pp, after := agreementProseP1Failures(t, private)
	r.PrivateHTML, r.PrivatePage, r.After, r.PrivateDiagnostics = pr.HTML, pp, after, pr.Diagnostics
	r.PrivateParts, partsOK = agreementCodeWindowParts(pr.HTML)
	if !partsOK {
		return r, false
	}
	for i, field := range fields {
		one := []byte(body)
		copy(one[field.OriginalTarget.Start:field.OriginalTarget.Stop], field.New)
		single := agreementMappedCodeP2Single{Field: i, Body: string(one), DiagnosticIndex: -1, Source: agreementMappedCodeP2Read(string(one))}
		sr, sp, failures := agreementProseP1Failures(t, single.Body)
		single.HTML, single.Page, single.Diagnostics, single.Failures = sr.HTML, sp, sr.Diagnostics, failures
		single.Parts, partsOK = agreementCodeWindowParts(sr.HTML)
		if !partsOK || len(raw.Diagnostics) != len(sr.Diagnostics) {
			return r, false
		}
		count := 0
		for di := range raw.Diagnostics {
			if !cmp.Equal(raw.Diagnostics[di], sr.Diagnostics[di]) {
				single.DiagnosticIndex = di
				count++
			}
		}
		if count != 1 {
			return r, false
		}
		r.Singles = append(r.Singles, single)
	}
	projectionOK := agreementCoupledMappedCodeProjection(&r)
	return r, projectionOK
}

type agreementCoupledMappedCodeDeclaration struct {
	Code              agreementMappedCodeP2Declaration
	ActiveCheckFields int
	P1Selected        string
}

func agreementCoupledMappedCodeP1Selected(r *agreementMappedCodeP2Declaration, active int) string {
	var selected *agreementFailure
	for i := range r.Before {
		if agreementSignature(&r.Before[i]) == r.Selected {
			if selected != nil {
				return ""
			}
			selected = &r.Before[i]
		}
	}
	if selected == nil || active < 0 || active >= len(r.Fields) || selected.Multiplicity != len(r.Fields) {
		return ""
	}
	counts := agreementCoupledMappedCodeP1Counts(&r.Page, &r.Source)
	quiet := len(r.Fields) - active
	if counts[selected.Tuple.Target] != quiet || agreementMappedCodeP2CitationCounts(r.Page.CodeCitations)[selected.Tuple] != len(r.Fields) {
		return ""
	}
	f := agreementFailure{Property: "P1", Identity: "citation-occurrences", Tuple: agreementCitation{Target: selected.Tuple.Target}, Direction: "page-only", Multiplicity: quiet}
	signature := agreementSignature(&f)
	matches := 0
	for i := range r.Before {
		if agreementSignature(&r.Before[i]) == signature {
			matches++
		}
	}
	if matches != 1 {
		return ""
	}
	return signature
}

func agreementCoupledMappedCodeDeclare(t *testing.T, body, name, signature string) (agreementCoupledMappedCodeDeclaration, bool) {
	t.Helper()
	code, owned := agreementCoupledMappedCodeReadDeclaration(t, body, name, signature)
	r := agreementCoupledMappedCodeDeclaration{Code: code}
	if !owned {
		return r, false
	}
	active, valid := agreementCoupledMappedCodeCheckFields(code.Body, code.Private, &code.Source, &code.PrivateSource, code.Fields)
	if !valid || active >= len(code.Fields) {
		return r, false
	}
	r.ActiveCheckFields = active
	r.P1Selected = agreementCoupledMappedCodeP1Selected(&code, active)
	return r, true
}

type agreementCoupledMappedCodeProspect struct {
	Body, Case, Selected, P1Selected string
	Eligible                         bool
}

