func agreementCoupledMappedCodeDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 {
		return "", "", ""
	}
	rows := agreementCoupledMappedCodeDeclarations()
	for i := range rows {
		r := &rows[i]
		code := &r.Code
		if c.Body != code.Body {
			continue
		}
		signature := agreementSignature(f)
		if signature != code.Selected && (r.P1Selected == "" || signature != r.P1Selected) {
			continue
		}
		if raw != code.HTML || !cmp.Equal(*page, code.Page) || !cmp.Equal(diagnostics, code.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(code.Before)) {
			return "", "", ""
		}
		var selected *agreementFailure
		for fi := range code.Before {
			if agreementSignature(&code.Before[fi]) == code.Selected {
				if selected != nil {
					return "", "", ""
				}
				selected = &code.Before[fi]
			}
		}
		if selected == nil {
			return "", "", ""
		}
		source := agreementMappedCodeP2Read(c.Body)
		private, fields, owned := agreementMappedCodeP2Physical(c.Body, selected, &source, code.Parts)
		if !owned || private != code.Private || !cmp.Equal(fields, code.Fields) || !cmp.Equal(source, code.Source) || !cmp.Equal(agreementMappedCodeP2Read(private), code.PrivateSource) || !agreementCoupledMappedCodeProjection(code) {
			return "", "", ""
		}
		active, valid := agreementCoupledMappedCodeCheckFields(code.Body, private, &source, &code.PrivateSource, fields)
		if !valid || active != r.ActiveCheckFields || agreementCoupledMappedCodeP1Selected(code, active) != r.P1Selected {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page"
	}
	return "", "", ""
}

func TestAgreementCoupledMappedCodeOwnedSource(t *testing.T) {
	t.Parallel()
	rows := agreementCoupledMappedCodeDeclarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			code := &r.Code
			if !cmp.Equal(code.Source, agreementMappedCodeP2Read(code.Body)) || !cmp.Equal(code.PrivateSource, agreementMappedCodeP2Read(code.Private)) {
				t.Fatal("caught: coupled code retains complete original and private readings")
			}
			for si := range code.Singles {
				single := &code.Singles[si]
				if !cmp.Equal(single.Source, agreementMappedCodeP2Read(single.Body)) {
					t.Fatal("caught: coupled code retains every complete single-field source reading")
				}
			}
			fresh, eligible := agreementCoupledMappedCodeDeclare(t, code.Body, code.Case, code.Selected)
			if !eligible || !cmp.Equal(*r, fresh) {
				t.Fatal("caught: complete coupled code source and whole private declaration")
			}
		})
	}
}

func TestAgreementCoupledMappedCodeOwnedPublic(t *testing.T) {
	t.Parallel()
	rows := agreementCoupledMappedCodeDeclarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			code := &r.Code
			raw, page, failures := agreementProseP1Failures(t, code.Body)
			if raw.HTML != code.HTML || !cmp.Equal(page, code.Page) || !cmp.Equal(raw.Diagnostics, code.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(code.Before)) {
				t.Fatal("caught: complete coupled code original public ledgers")
			}
			for fi := range failures {
				f := &failures[fi]
				signature := agreementSignature(f)
				if signature != code.Selected && (r.P1Selected == "" || signature != r.P1Selected) {
					continue
				}
				kind, authority, wrong := agreementCoupledMappedCodeDifference(agreementCase{Body: code.Body}, f, raw.HTML, &page, raw.Diagnostics, failures)
				if kind != "debt" || authority != "#1011 stage 5" || wrong != "page" {
					t.Fatal("caught: coupled code and complete P1 scope name page debt")
				}
			}
			private, pp, after := agreementProseP1Failures(t, code.Private)
			if private.HTML != code.PrivateHTML || !cmp.Equal(pp, code.PrivatePage) || !cmp.Equal(private.Diagnostics, code.PrivateDiagnostics) || !maps.Equal(agreementMixedCurrent(after), agreementMixedCurrent(code.After)) {
				t.Fatal("caught: complete coupled code private public ledgers")
			}
			for si := range code.Singles {
				single := &code.Singles[si]
				sr, sp, sf := agreementProseP1Failures(t, single.Body)
				parts, valid := agreementCodeWindowParts(sr.HTML)
				if !valid || sr.HTML != single.HTML || !cmp.Equal(sp, single.Page) || !cmp.Equal(parts, single.Parts) || !cmp.Equal(sr.Diagnostics, single.Diagnostics) || !maps.Equal(agreementMixedCurrent(sf), agreementMixedCurrent(single.Failures)) {
					t.Fatal("caught: complete coupled code single-field public ledgers")
				}
			}
			if !agreementCoupledMappedCodeProjection(code) {
				t.Fatal("caught: complete coupled code and P1 signed projections")
			}
		})
	}
}

func TestAgreementCoupledMappedCodeOwnedCensus(t *testing.T) {
	t.Parallel()
	prospects := agreementCoupledMappedCodeProspects()
	if len(prospects) != 88 || len(agreementCoupledMappedCodeDeclarations()) != 10 {
		t.Fatal("caught: whole coupled code prospect and owned declaration census")
	}
	for i := range prospects {
		p := &prospects[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			r, eligible := agreementCoupledMappedCodeDeclare(t, p.Body, p.Case, p.Selected)
			if eligible != p.Eligible || r.P1Selected != p.P1Selected {
				t.Fatal("caught: every coupled code and whole P1 prospect is independently recomputed")
			}
		})
	}
}

func TestAgreementCoupledMappedCodeOwnedRefusals(t *testing.T) {
	t.Parallel()
	rows := agreementCoupledMappedCodeDeclarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			code := &r.Code
			f := agreementMappedCodeP2Selected(t, code)
			refuse := func(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, before []agreementFailure) {
				t.Helper()
				if kind, _, _ := agreementCoupledMappedCodeDifference(c, f, raw, page, diagnostics, before); kind != "" {
					t.Fatal("caught: coupled code refuses changed whole source or public context")
				}
			}
			refuse(agreementCase{Body: code.Body}, nil, code.HTML, &code.Page, code.Diagnostics, code.Before)
			refuse(agreementCase{Body: code.Body}, &f, code.HTML, nil, code.Diagnostics, code.Before)
			refuse(agreementCase{Body: code.Body + "!"}, &f, code.HTML, &code.Page, code.Diagnostics, code.Before)
			refuse(agreementCase{Body: code.Body, Title: "outside"}, &f, code.HTML, &code.Page, code.Diagnostics, code.Before)
			refuse(agreementCase{Body: code.Body, Companions: capturedBodies{"outside.md": "outside"}}, &f, code.HTML, &code.Page, code.Diagnostics, code.Before)
			refuse(agreementCase{Body: code.Body}, &f, code.HTML+"!", &code.Page, code.Diagnostics, code.Before)
			page := code.Page
			page.Headings = append(slices.Clone(page.Headings), "outside")
			refuse(agreementCase{Body: code.Body}, &f, code.HTML, &page, code.Diagnostics, code.Before)
			diagnostics := append(slices.Clone(code.Diagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			refuse(agreementCase{Body: code.Body}, &f, code.HTML, &code.Page, diagnostics, code.Before)
			before := append(slices.Clone(code.Before), agreementFailure{Property: "P0", Identity: "outside", Multiplicity: 1})
			refuse(agreementCase{Body: code.Body}, &f, code.HTML, &code.Page, code.Diagnostics, before)
			for fi := range code.Before {
				partial := &code.Before[fi]
				if partial.Property == "P1" && agreementSignature(partial) != r.P1Selected {
					refuse(agreementCase{Body: code.Body}, partial, code.HTML, &code.Page, code.Diagnostics, code.Before)
				}
			}
		})
	}
}

func TestAgreementCoupledMappedCodeOwnedProjectionRefusals(t *testing.T) {
	t.Parallel()
	rows := agreementCoupledMappedCodeDeclarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			for _, edit := range []func(*agreementMappedCodeP2Declaration){
				func(r *agreementMappedCodeP2Declaration) {
					r.Before = append(r.Before, agreementFailure{Property: "P0", Identity: "outside", Multiplicity: 1})
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.Before = append(r.Before, agreementFailure{Property: "P1", Identity: "citation-occurrences", Tuple: agreementCitation{Target: "outside"}, Direction: "page-only", Multiplicity: 1})
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.After = append(r.After, agreementFailure{Property: "P1", Identity: "citation-occurrences", Tuple: agreementCitation{Target: "outside"}, Direction: "page-only", Multiplicity: 1})
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.After = append(r.After, agreementFailure{Property: "P3", Identity: "outside", Fragment: "outside", Multiplicity: 1})
				},
				func(r *agreementMappedCodeP2Declaration) { r.After = nil },
				func(r *agreementMappedCodeP2Declaration) {
					r.PrivatePage.Headings = append(r.PrivatePage.Headings, "outside")
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.PrivateSource.Sites = append(r.PrivateSource.Sites, agreementNativeCodePayloadSite{Kind: "outside"})
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.PrivateSource.Check.Targets = append(r.PrivateSource.Check.Targets, "outside")
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.Source.Check.Targets = append(r.Source.Check.Targets, "outside")
				},
				func(r *agreementMappedCodeP2Declaration) { r.PrivateSource.NeutralPositions = nil },
				func(r *agreementMappedCodeP2Declaration) { r.Singles[0].Field = -1 },
				func(r *agreementMappedCodeP2Declaration) { r.Singles[0].Body += "!" },
				func(r *agreementMappedCodeP2Declaration) { r.Singles[0].DiagnosticIndex = -1 },
				func(r *agreementMappedCodeP2Declaration) {
					r.Singles[0].Diagnostics[r.Singles[0].DiagnosticIndex].Message = "outside"
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.PrivateDiagnostics = append(r.PrivateDiagnostics, render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
				},
				func(r *agreementMappedCodeP2Declaration) { r.Fields[0].OriginalTarget.Start-- },
				func(r *agreementMappedCodeP2Declaration) { r.PrivateSource.Check.Fields[0].Word += "!" },
			} {
				changed := agreementMappedCodeP2Clone(t, &r.Code)
				edit(&changed)
				if agreementCoupledMappedCodeProjection(&changed) {
					t.Fatal("caught: coupled code refuses changed whole field, code or P1 projection")
				}
			}
		})
	}
}

func TestAgreementCoupledMappedCodeOwnedCheckFieldRefusals(t *testing.T) {
	t.Parallel()
	rows := agreementCoupledMappedCodeDeclarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			code := &r.Code
			refuse := func(body, private string, source, changed *agreementMappedCodeP2Reading, fields []agreementMappedCodeP2Field) {
				t.Helper()
				if _, valid := agreementCoupledMappedCodeCheckFields(body, private, source, changed, fields); valid {
					t.Fatal("caught: coupled code refuses borrowed, duplicate or changed whole check fields")
				}
			}
			refuse(code.Body, code.Private, nil, &code.PrivateSource, code.Fields)
			refuse(code.Body, code.Private, &code.Source, nil, code.Fields)
			refuse(code.Body, code.Private, &code.Source, &code.PrivateSource, nil)
			refuse(code.Body, code.Private+"!", &code.Source, &code.PrivateSource, code.Fields)
			private := []byte(code.Private)
			private[0] ^= 1
			refuse(code.Body, string(private), &code.Source, &code.PrivateSource, code.Fields)
			duplicate := append(slices.Clone(code.Fields), code.Fields[0])
			refuse(code.Body, code.Private, &code.Source, &code.PrivateSource, duplicate)
			badFields := slices.Clone(code.Fields)
			badFields[0].OriginalField.Stop++
			refuse(code.Body, code.Private, &code.Source, &code.PrivateSource, badFields)
			badFields = slices.Clone(code.Fields)
			badFields[0].OriginalTarget.Start--
			refuse(code.Body, code.Private, &code.Source, &code.PrivateSource, badFields)
			changed := agreementMappedCodeP2Clone(t, code)
			changed.PrivateSource.Check.Targets = append(changed.PrivateSource.Check.Targets, "outside")
			refuse(changed.Body, changed.Private, &changed.Source, &changed.PrivateSource, changed.Fields)
			changed = agreementMappedCodeP2Clone(t, code)
			changed.Source.Check.Targets = append(changed.Source.Check.Targets, "outside")
			refuse(changed.Body, changed.Private, &changed.Source, &changed.PrivateSource, changed.Fields)
			changed = agreementMappedCodeP2Clone(t, code)
			changed.PrivateSource.Check.Fields[0].Word += "!"
			refuse(changed.Body, changed.Private, &changed.Source, &changed.PrivateSource, changed.Fields)
			changed = agreementMappedCodeP2Clone(t, code)
			changed.PrivateSource.Check.Fields[0].Code = !changed.PrivateSource.Check.Fields[0].Code
			refuse(changed.Body, changed.Private, &changed.Source, &changed.PrivateSource, changed.Fields)
		})
	}
}
